/**
 * Real-photograph lookup for map markers and the unit panel.
 * Data: ./manifest.json (generated by scripts/art/build.mjs). Credits: ./credits.json, docs/IMAGE_CREDITS.md.
 * Pure + deterministic (no randomness): same inputs always return the same photo.
 */
import type { NationId, UnitType } from '../core/types';
import manifestJson from './manifest.json';

export type PhotoRole = 'hq' | 'combat';

export interface PhotoEntry {
  id: string;
  category: UnitType;
  /** 'hq' for headquarters/staff/command-post/signals photos, 'combat' otherwise. */
  role?: PhotoRole;
  alsoTypes: UnitType[];
  nation: NationId;
  subject: string;
  equipmentKeys: string[];
  tags: string[];
  thumb: string;
  panel: string;
  license: string;
  author: string;
  sourceUrl: string;
  retrieved: string;
  credit: string;
}

export interface UnitPhoto {
  /** 256x256 WebP, subject-centred - for map markers. URL already includes the Vite base path. */
  thumb: string;
  /** 640x400 JPEG - for the unit panel. */
  panel: string;
  /** One-line credit: "subject - author - licence - source url". Show in the panel footer / Credits screen. */
  credit: string;
  /** Human-readable description of what the photo actually shows (use as alt text). */
  subject: string;
  /** 'hq' for headquarters/staff/command-post/signals photos. HQ units only ever get 'hq' photos, other units never do. */
  role: PhotoRole;
}

const MANIFEST = manifestJson as PhotoEntry[];
const BASE = (import.meta.env?.BASE_URL ?? '/').replace(/\/?$/, '/');
const url = (p: string) => BASE + p.replace(/^\//, '');

/** Equipment keys that identify a unit's "main" kit, strongest first when a unit has several. */
export const EQUIPMENT_PRIORITY = ['tank_heavy', 'tank_medium', 'tank_light', 'armoured_car', 'gun_at', 'gun_arty', 'gun_aa', 'halftrack', 'carrier', 'truck', 'rifle'] as const;

/** Unit types that may fall back to nation-neutral photos (generic trucks/convoys/HQ scenes with no identifiable national markings). */
const NEUTRAL_FALLBACK_TYPES: readonly UnitType[] = ['logistics', 'motorised', 'hq'];

function pickBest(type: UnitType, nation: NationId, hint: string | undefined): PhotoEntry[] {
  let best: PhotoEntry[] = [];
  let bestScore = 0;
  const wantHq = type === 'hq';
  for (const e of MANIFEST) {
    if (e.nation !== nation) continue;
    if ((e.role === 'hq' || e.category === 'hq') !== wantHq) continue; // HQ units <-> HQ photos only
    const s = wantHq ? 10 : score(e, type, hint);
    if (s <= 0) continue;
    if (s > bestScore) { bestScore = s; best = [e]; } else if (s === bestScore) best.push(e);
  }
  return best;
}

function score(e: PhotoEntry, type: UnitType, hint: string | undefined): number {
  // A photo is only eligible when its category (or alsoTypes) includes the requested unit type;
  // a hint can then only rank between eligible photos (a gun hint never turns infantry into a gun photo).
  let s = 0;
  if (e.category === type) s = 10;
  else if (e.alsoTypes.includes(type)) s = 4;
  else return 0;
  const h = hint?.toLowerCase().trim();
  if (h && (e.equipmentKeys.includes(h) || e.tags.some(t => h.includes(t) || t.includes(h)) || e.subject.toLowerCase().includes(h))) s += 100;
  return s;
}

/** Deterministic string hash (FNV-1a) used only to rotate between equally good photos. */
function hash(str: string): number {
  let x = 2166136261;
  for (let i = 0; i < str.length; i++) { x ^= str.charCodeAt(i); x = Math.imul(x, 16777619); }
  return x >>> 0;
}

/**
 * Best photo for a unit.
 * @param type  the unit's UnitType
 * @param nation the unit's nation (exact match only; a German unit never gets a British photo)
 * @param hint  optional: an equipment key ('tank_medium','gun_arty','gun_at','tank_light','truck','armoured_car','rifle', ...)
 *              or free text ('somua', 'panzer iv'). Use the unit's main equipment key (see mainEquipmentKey).
 * @param variantSeed optional stable string (e.g. unit id) to rotate between equally good photos; omit for the first.
 * @returns photo or null when no honest match exists (UI must then fall back to the drawn icon).
 */
export function unitPhoto(type: UnitType, nation: NationId, hint?: string, variantSeed?: string): UnitPhoto | null {
  let best = pickBest(type, nation, hint);
  // No photo of the unit's own nation: only logistics/motorised/HQ may use a NEUTRAL (unmarked, generic) photo; everything else gets null.
  if (!best.length && nation !== 'NEUTRAL' && NEUTRAL_FALLBACK_TYPES.includes(type)) best = pickBest(type, 'NEUTRAL', hint);
  if (!best.length) return null;
  best.sort((a, b) => (a.id < b.id ? -1 : 1));
  const pick = best[variantSeed ? hash(variantSeed) % best.length : 0];
  return { thumb: url(pick.thumb), panel: url(pick.panel), credit: pick.credit, subject: pick.subject, role: pick.role === 'hq' || pick.category === 'hq' ? 'hq' : 'combat' };
}

/** Unit types whose photo is a soldier/vehicle group, never a support weapon: for these only 'rifle' (or nothing) is a valid hint. */
const FOOT_TYPES: readonly UnitType[] = ['infantry', 'paratroop', 'engineer', 'hq'];

/** Pick the hint key from a unit's `equipment.held` map using EQUIPMENT_PRIORITY. Pass the unit type so infantry-like units never hint a support weapon. */
export function mainEquipmentKey(held: Record<string, number>, type?: UnitType): string | undefined {
  if (type && FOOT_TYPES.includes(type)) return (held.rifle ?? 0) > 0 ? 'rifle' : undefined;
  for (const k of EQUIPMENT_PRIORITY) if ((held[k] ?? 0) > 0) return k;
  return undefined;
}

/** All entries (for a Credits screen). */
export function allPhotoCredits(): { id: string; nation: NationId; subject: string; author: string; license: string; sourceUrl: string }[] {
  return MANIFEST.map(e => ({ id: e.id, nation: e.nation, subject: e.subject, author: e.author, license: e.license, sourceUrl: e.sourceUrl }));
}
